/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds;
    QueryRun                queryRun;
    PriceDiscTable          priceDiscTable;
    ;

    qbds = query.addDataSource(tableNum(PriceDiscTable));
    qbds.addRange(fieldNum(PriceDiscTable, AccountCode));
    qbds.addRange(fieldnum(PriceDiscTable, relation));
    qbds.addRange(fieldNum(PriceDiscTable, AccountRelation));

    queryRun = new QueryRun(query);
    if(queryRun.prompt())
    {
        while(queryRun.next())
        {
            ttsbegin;
            priceDiscTable = queryRun.get(tableNum(PriceDiscTable));
            priceDiscTable.selectForUpdate(true);
            if(priceDiscTable.validateDelete())
            {
                priceDiscTable.delete();
            }
            ttscommit;
        }
    }
}
